-- ============================================================================
-- SEED DATA DE PRUEBAS - TPI FULVO
-- 3 Torneos para testeo de endpoints futuros:
-- 1) Torneo LIGA (Iniciado, 10 equipos cupo 100%, 45 partidos Round Robin)
-- 2) Torneo LIGA (Abierto inscripción, cupo 10, 3 equipos inscriptos, 7 cupos libres)
-- 3) Torneo LLAVES (Iniciado, 8 equipos cupo 100%, 7 partidos Cuartos/Semi/Final)
-- ============================================================================

-- Asegurar esquemas
CREATE SCHEMA IF NOT EXISTS esquema_torneos;
CREATE SCHEMA IF NOT EXISTS esquema_operaciones;

-- Asegurar tablas de esquema_torneos
CREATE TABLE IF NOT EXISTS esquema_torneos.torneo (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(150) NOT NULL,
    formato VARCHAR(20) NOT NULL,
    cupo_equipos INTEGER NOT NULL,
    estado VARCHAR(30) NOT NULL,
    fecha_inicio TIMESTAMP WITHOUT TIME ZONE,
    fecha_creacion TIMESTAMP WITHOUT TIME ZONE NOT NULL
);

CREATE TABLE IF NOT EXISTS esquema_torneos.solicitud_inscripcion (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    torneo_id BIGINT NOT NULL REFERENCES esquema_torneos.torneo(id),
    fanatico_usuario_id VARCHAR(100) NOT NULL,
    nombre_equipo VARCHAR(100) NOT NULL,
    estado VARCHAR(30) NOT NULL,
    fecha_solicitud TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    motivo_rechazo VARCHAR(255),
    datos_plantel_json TEXT
);

CREATE TABLE IF NOT EXISTS esquema_torneos.equipo (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    torneo_id BIGINT NOT NULL REFERENCES esquema_torneos.torneo(id),
    solicitud_id BIGINT NOT NULL UNIQUE REFERENCES esquema_torneos.solicitud_inscripcion(id),
    nombre VARCHAR(100) NOT NULL,
    delegado_usuario_id VARCHAR(100) NOT NULL,
    estado VARCHAR(30) NOT NULL,
    cambios_realizados INTEGER NOT NULL DEFAULT 0,
    fecha_alta TIMESTAMP WITHOUT TIME ZONE NOT NULL
);

CREATE TABLE IF NOT EXISTS esquema_torneos.jugador (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dni VARCHAR(20) NOT NULL,
    equipo_id BIGINT NOT NULL REFERENCES esquema_torneos.equipo(id),
    nombre VARCHAR(100) NOT NULL,
    apellido VARCHAR(100) NOT NULL,
    dorsal INTEGER NOT NULL,
    posicion VARCHAR(30) NOT NULL,
    es_capitan BOOLEAN NOT NULL DEFAULT false,
    activo BOOLEAN NOT NULL DEFAULT true,
    suspendido BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS esquema_operaciones.partido (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    torneo_id BIGINT NOT NULL,
    formato_torneo VARCHAR(255) NOT NULL,
    fecha_o_fase INTEGER NOT NULL,
    equipo_local_id BIGINT,
    equipo_visitante_id BIGINT,
    fecha_hora TIMESTAMP WITHOUT TIME ZONE,
    estado VARCHAR(255) NOT NULL
);

-- Limpieza idempotente previa de los 3 torneos de testeo
DELETE FROM esquema_operaciones.partido WHERE torneo_id IN (1, 2, 3);
DELETE FROM esquema_torneos.jugador WHERE equipo_id IN (SELECT id FROM esquema_torneos.equipo WHERE torneo_id IN (1, 2, 3));
DELETE FROM esquema_torneos.equipo WHERE torneo_id IN (1, 2, 3);
DELETE FROM esquema_torneos.solicitud_inscripcion WHERE torneo_id IN (1, 2, 3);
DELETE FROM esquema_torneos.torneo WHERE id IN (1, 2, 3);

-- 1. Torneo 1: Formato LIGA - Estado INICIADO con cupos completos (10/10)
