-- Sincronizar secuencias de identidad para que los futuros INSERT no colisionen con los IDs precargados
SELECT setval(pg_get_serial_sequence('esquema_torneos.torneo', 'id'), (SELECT COALESCE(MAX(id), 1) FROM esquema_torneos.torneo));
SELECT setval(pg_get_serial_sequence('esquema_torneos.solicitud_inscripcion', 'id'), (SELECT COALESCE(MAX(id), 1) FROM esquema_torneos.solicitud_inscripcion));
SELECT setval(pg_get_serial_sequence('esquema_torneos.equipo', 'id'), (SELECT COALESCE(MAX(id), 1) FROM esquema_torneos.equipo));
SELECT setval(pg_get_serial_sequence('esquema_torneos.jugador', 'id'), (SELECT COALESCE(MAX(id), 1) FROM esquema_torneos.jugador));
SELECT setval(pg_get_serial_sequence('esquema_operaciones.partido', 'id'), (SELECT COALESCE(MAX(id), 1) FROM esquema_operaciones.partido));
